import urllib.request, json, time

def get(url, timeout=30):
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=timeout).read()

ids = [l.strip() for l in open('pdb_ids.txt') if l.strip()]

for pid in ids:
    try:
        data = json.loads(get(f"https://data.rcsb.org/rest/v1/core/entry/{pid}"))
        nonpoly = data.get('rcsb_entry_container_identifiers',{}).get('non_polymer_entity_ids',[])
        if nonpoly:
            for e in nonpoly:
                try:
                    ent = json.loads(get(f"https://data.rcsb.org/rest/v1/core/nonpolymer_entity/{pid}/{e}"))
                    comp = ent.get('pdbx_entity_nonpoly',{})
                    comp_id = comp.get('comp_id','')
                    name = comp.get('name','')
                    formula = comp.get('formula','')
                    smiles = comp.get('pdbx_smiles','')
                    inchi = comp.get('pdbx_inchi','')
                    print(f"{pid} entity {e}: comp_id={comp_id}, name={name}, formula={formula}")
                    if smiles: print(f"  SMILES: {smiles}")
                    if inchi: print(f"  InChI: {inchi}")
                except Exception as ex:
                    print(f"{pid} entity {e}: ERROR {ex}")
                time.sleep(0.2)
    except Exception as ex:
        print(f"{pid}: ERROR {ex}")
    time.sleep(0.2)
